/**
 * Curated list catalog: expert "best of" lists to check against the owner's
 * ranked list. Each entry's artist/title feeds the existing MusicBrainz
 * search box (see curatedListMatch.ts and main.ts's handleRateCuratedAlbum)
 * for anything without a `resolved` record, so there's no separate ingestion
 * pipeline to keep in sync with search-album.ts's own resolution.
 *
 * `resolved` is populated offline by web/scripts/resolve-curated-list-mbids.mjs
 * (a field-scoped MusicBrainz query + score>=90 confidence bar, or a direct
 * hit against the owner's own already-ranked albums) -- not hand-authored.
 * Its absence means the resolver couldn't confidently place that entry; the
 * app falls back to a live search with an owner confirm step before insert.
 *
 * Adding/updating a list: edit this file: the view reads CURATED_LISTS as-is.
 */
import type { Album } from '../ranking/types';

export type CuratedAlbumEntry = {
  rank: number;
  artist: string;
  title: string;
  resolved?: Album;
};

export type CuratedList = {
  name: string;
  source: string;
  albums: CuratedAlbumEntry[];
};

